import{_ as e,c as t,o as i,a2 as r}from"./chunks/framework.gSKzFT2J.js";const h=JSON.parse(`{"title":"Qu'est-ce que Git ?","description":"","frontmatter":{},"headers":[],"relativePath":"fr/introduction.md","filePath":"fr/introduction.md"}`),s={name:"fr/introduction.md"},o=r('<h1 id="qu-est-ce-que-git" tabindex="-1">Qu&#39;est-ce que Git ? <a class="header-anchor" href="#qu-est-ce-que-git" aria-label="Permalink to &quot;Qu&#39;est-ce que Git ?&quot;">​</a></h1><p>Git est un système de gestion de versions très populaire. Il a été créé par Linus Torvalds en 2005 et est maintenu depuis par Junio Hamano.</p><p>Git est utilisé pour :</p><ul><li>Suivre les modifications du code</li><li>Identifier qui a effectué des changements</li><li>Faciliter la collaboration sur le code</li></ul><h2 id="que-fait-git" tabindex="-1">Que fait Git ? <a class="header-anchor" href="#que-fait-git" aria-label="Permalink to &quot;Que fait Git ?&quot;">​</a></h2><p>Git permet de :</p><ul><li>Gérer des projets à l&#39;aide de <strong>dépôts (repositories)</strong></li><li><strong>Cloner</strong> un projet pour travailler sur une copie locale</li><li><strong>Contrôler et suivre les modifications</strong> avec la mise en scène (<em>staging</em>) et la validation (<em>committing</em>)</li><li><strong>Créer des branches et fusionner</strong> (<em>merge</em>) pour travailler sur différentes parties et versions d&#39;un projet</li><li><strong>Récupérer la dernière version</strong> d&#39;un projet avec <em>pull</em></li><li><strong>Envoyer des mises à jour locales</strong> vers le projet principal avec <em>push</em></li></ul><h2 id="travailler-avec-git" tabindex="-1">Travailler avec Git <a class="header-anchor" href="#travailler-avec-git" aria-label="Permalink to &quot;Travailler avec Git&quot;">​</a></h2><ol><li><strong>Initialiser un dépôt Git</strong> dans un dossier avec <code>git init</code></li><li>Git crée alors un dossier caché <code>.git</code> qui suivra les changements</li><li>Lorsqu&#39;un fichier est <strong>modifié, ajouté ou supprimé</strong>, il est marqué comme &quot;modifié&quot;</li><li>Les fichiers modifiés peuvent être ajoutés à la zone de <strong>mise en scène</strong> (<em>staging</em>)</li><li>Une fois mis en scène, les fichiers sont <strong>validés</strong> (<em>committed</em>), ce qui enregistre un instantané permanent</li><li>Git permet d&#39;afficher <strong>l&#39;historique complet</strong> de toutes les validations</li><li>Il est possible de <strong>revenir à une version précédente</strong> grâce à l&#39;historique des commits</li><li>Git ne stocke pas une copie complète de chaque fichier à chaque commit, mais enregistre uniquement les différences (<em>diffs</em>)</li></ol><h2 id="plateformes-compatibles" tabindex="-1">Plateformes compatibles <a class="header-anchor" href="#plateformes-compatibles" aria-label="Permalink to &quot;Plateformes compatibles&quot;">​</a></h2><p>Git peut être utilisé avec plusieurs plateformes d&#39;hébergement de code, notamment :</p><ul><li><a href="https://github.com/" target="_blank" rel="noreferrer">GitHub</a> 🔄</li><li><a href="https://bitbucket.org/" target="_blank" rel="noreferrer">Bitbucket</a> 🔄</li><li><a href="https://gitlab.com/" target="_blank" rel="noreferrer">GitLab</a> 🔄</li></ul><h2 id="pourquoi-utiliser-git" tabindex="-1">Pourquoi utiliser Git ? <a class="header-anchor" href="#pourquoi-utiliser-git" aria-label="Permalink to &quot;Pourquoi utiliser Git ?&quot;">​</a></h2><p>✅ Plus de <strong>70 % des développeurs</strong> utilisent Git 📊 ✅ Collaboration facilitée entre développeurs, <strong>où qu&#39;ils soient</strong> dans le monde 🌍 ✅ Historique complet des modifications 🔍 ✅ Possibilité de <strong>revenir à une version précédente</strong> sans perte de données 🔄</p><hr><h1 id="qu-est-ce-que-github" tabindex="-1">Qu&#39;est-ce que GitHub ? <a class="header-anchor" href="#qu-est-ce-que-github" aria-label="Permalink to &quot;Qu&#39;est-ce que GitHub ?&quot;">​</a></h1><p>💡 <strong>Git et GitHub ne sont pas la même chose !</strong></p><ul><li>GitHub fournit des outils qui utilisent Git 📂</li><li>GitHub est la <strong>plus grande plateforme d&#39;hébergement de code</strong> au monde 🌎</li><li>GitHub appartient à <strong>Microsoft depuis 2018</strong> 🏢</li></ul><p>Dans ce guide, nous nous concentrerons sur l&#39;utilisation de Git avec GitHub 🚀</p>',19),a=[o];function n(l,u,c,d,m,p){return i(),t("div",null,a)}const f=e(s,[["render",n]]);export{h as __pageData,f as default};
